changeSet.sql:
INSERT INTO tag (created_at, updated_at, name, status) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Food', 'APPROVED' WHERE NOT EXISTS ( SELECT 1 FROM tag WHERE name = 'Food' );
INSERT INTO tag (created_at, updated_at, name, status) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'Training', 'APPROVED' WHERE NOT EXISTS ( SELECT 1 FROM tag WHERE name = 'Training' );
INSERT INTO tag_chart_type_link (created_at, updated_at, tag_id, chart_type) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, t.id, 'CALORIES_PER_DAY' FROM tag t WHERE t.name = 'Food' AND NOT EXISTS ( SELECT 1 FROM tag_chart_type_link link WHERE link.tag_id = t.id AND link.chart_type = 'CALORIES_PER_DAY' );
INSERT INTO tag_chart_type_link (created_at, updated_at, tag_id, chart_type) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, t.id, 'PFC_PER_DAY' FROM tag t WHERE t.name = 'Food' AND NOT EXISTS ( SELECT 1 FROM tag_chart_type_link link WHERE link.tag_id = t.id AND link.chart_type = 'PFC_PER_DAY' );
INSERT INTO tag_chart_type_link (created_at, updated_at, tag_id, chart_type) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, t.id, 'CALORIES_PER_EATING' FROM tag t WHERE t.name = 'Food' AND NOT EXISTS ( SELECT 1 FROM tag_chart_type_link link WHERE link.tag_id = t.id AND link.chart_type = 'CALORIES_PER_EATING' );
INSERT INTO tag_chart_type_link (created_at, updated_at, tag_id, chart_type) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, t.id, 'PFC_PER_EATING' FROM tag t WHERE t.name = 'Food' AND NOT EXISTS ( SELECT 1 FROM tag_chart_type_link link WHERE link.tag_id = t.id AND link.chart_type = 'PFC_PER_EATING' );
